∀ {α : Type u_1} {G : RDF11.Set α} {triples : List α} {nodup : triples.Nodup}
  {membership : ∀ (t : α), t ∈ triples ↔ G t} {triples_1 : List α} {nodup_1 : triples_1.Nodup}
  {membership_1 : ∀ (t : α), t ∈ triples_1 ↔ G t},
  { triples := triples, nodup := nodup, membership := membership } =
      { triples := triples_1, nodup := nodup_1, membership := membership_1 } →
    triples = triples_1

∀ {Iri Literal : Type} (s : Iri),
  RDF11.GeneralizedScope.originalTriple s =
    { subject := RDF11.Term.iri s, predicate := RDF11.Term.blank (), object := RDF11.Term.iri s }

∀ {Iri Literal : Type} (s p : Iri),
  RDF11.GeneralizedScope.substitutedTriple s p =
    { subject := RDF11.Term.iri s, predicate := RDF11.Term.iri p, object := RDF11.Term.iri s }

∀ {Iri Literal B : Type} {G H : RDF11.GeneralizedGraph Iri Literal B} {toFun invFun : B → B}
  {left_inv : ∀ (b : B), G.hasBlank b → invFun (toFun b) = b}
  {right_inv : ∀ (b : B), H.hasBlank b → toFun (invFun b) = b} {image_eq : RDF11.GeneralizedGraph.mapBlank toFun G = H}
  {toFun_1 invFun_1 : B → B} {left_inv_1 : ∀ (b : B), G.hasBlank b → invFun_1 (toFun_1 b) = b}
  {right_inv_1 : ∀ (b : B), H.hasBlank b → toFun_1 (invFun_1 b) = b}
  {image_eq_1 : RDF11.GeneralizedGraph.mapBlank toFun_1 G = H},
  { toFun := toFun, invFun := invFun, left_inv := left_inv, right_inv := right_inv, image_eq := image_eq } =
      { toFun := toFun_1, invFun := invFun_1, left_inv := left_inv_1, right_inv := right_inv_1,
        image_eq := image_eq_1 } →
    toFun = toFun_1 ∧ invFun = invFun_1

∀ {Iri Literal : Type} {U : Type u} {IR : RDF11.Set U} {IR_nonempty : ∃ x, IR x} {IP : RDF11.Set U}
  {IEXT : { p // IP p } → RDF11.Set ({ x // IR x } × { y // IR y })} {IS : Iri → { x // IR x ∨ IP x }}
  {IL : Literal → Option { x // IR x }} {IR_1 : RDF11.Set U} {IR_nonempty_1 : ∃ x, IR_1 x} {IP_1 : RDF11.Set U}
  {IEXT_1 : { p // IP_1 p } → RDF11.Set ({ x // IR_1 x } × { y // IR_1 y })} {IS_1 : Iri → { x // IR_1 x ∨ IP_1 x }}
  {IL_1 : Literal → Option { x // IR_1 x }},
  { IR := IR, IR_nonempty := IR_nonempty, IP := IP, IEXT := IEXT, IS := IS, IL := IL } =
      { IR := IR_1, IR_nonempty := IR_nonempty_1, IP := IP_1, IEXT := IEXT_1, IS := IS_1, IL := IL_1 } →
    IR = IR_1 ∧ IP = IP_1 ∧ IEXT ≍ IEXT_1 ∧ IS ≍ IS_1 ∧ IL ≍ IL_1

∀ {Iri Literal B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (sk : RDF11.Skolemization datatype G) {b : B},
  G.hasBlank b → RDF11.GeneralizedGraph.vocabulary datatype sk.graph (Sum.inl (sk.name b))

∀ {Literal Iri B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (self : RDF11.Skolemization datatype G) (b : B),
  G.hasBlank b → ¬RDF11.GeneralizedGraph.vocabulary datatype G (Sum.inl (self.name b))

∀ {Iri Literal B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (sk : RDF11.Skolemization datatype G) (i : Iri),
  sk.inverseTerm (RDF11.Term.iri i) = (Option.map RDF11.Term.blank (sk.unname i)).getD (RDF11.Term.iri i)

∀ {Iri Literal B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (sk : RDF11.Skolemization datatype G) (q : RDF11.Term Iri Literal B),
  (∀ (b : B), G.hasBlank b → ¬RDF11.Term.names datatype q (Sum.inl (sk.name b))) → sk.inverseTerm q = q

∀ {Iri Literal B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (sk : RDF11.Skolemization datatype G) (t : RDF11.GeneralizedTriple Iri Literal B),
  sk.inverseTriple t =
    { subject := sk.inverseTerm t.subject, predicate := sk.inverseTerm t.predicate, object := sk.inverseTerm t.object }

∀ {Iri Literal B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (sk : RDF11.Skolemization datatype G) (t : RDF11.GeneralizedTriple Iri Literal B),
  G t → sk.inverseTriple (RDF11.GeneralizedTriple.substitute sk.substitution t) = t

∀ {Literal Iri B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B} {name : B → Iri}
  {injective : ∀ (b c : B), G.hasBlank b → G.hasBlank c → name b = name c → b = c}
  {fresh : ∀ (b : B), G.hasBlank b → ¬RDF11.GeneralizedGraph.vocabulary datatype G (Sum.inl (name b))}
  {name_1 : B → Iri} {injective_1 : ∀ (b c : B), G.hasBlank b → G.hasBlank c → name_1 b = name_1 c → b = c}
  {fresh_1 : ∀ (b : B), G.hasBlank b → ¬RDF11.GeneralizedGraph.vocabulary datatype G (Sum.inl (name_1 b))},
  { name := name, injective := injective, fresh := fresh } =
      { name := name_1, injective := injective_1, fresh := fresh_1 } →
    name = name_1

∀ {Iri Literal B : Type} {datatype : Literal → Iri} {G : RDF11.GeneralizedGraph Iri Literal B}
  (sk : RDF11.Skolemization datatype G) (i : Iri),
  sk.unname i = if h : ∃ b, G.hasBlank b ∧ sk.name b = i then some (Classical.choose h) else none

∀ {Iri Literal Blank : Type} {subject : RDF11.Subject Iri Blank} {predicate : Iri}
  {object : RDF11.Term Iri Literal Blank} {subject_1 : RDF11.Subject Iri Blank} {predicate_1 : Iri}
  {object_1 : RDF11.Term Iri Literal Blank},
  { subject := subject, predicate := predicate, object := object } =
      { subject := subject_1, predicate := predicate_1, object := object_1 } →
    subject = subject_1 ∧ predicate = predicate_1 ∧ object = object_1

∀ {Iri Literal B₁ B₂ B₃ : Type} {G : RDF11.GeneralizedGraph Iri Literal B₁} {H : RDF11.GeneralizedGraph Iri Literal B₂}
  {E : RDF11.GeneralizedGraph Iri Literal B₃},
  RDF11.SimplyEntails G H → RDF11.SimplyEntails H E → RDF11.SimplyEntails G E
